function codeOrder_grid (order){

 
if (order == "2" ) { 
    let $tr = $('.cf-desktop-grid .cf-table-layout__row--head');
    let $thElements = $tr.children('th');
    var exclusive_item_count = $(".cf-desktop-grid .exclusive_item").length;
    reverse_grid_s_order($tr, $thElements, exclusive_item_count)
    $('.cf-desktop-grid .cf-table-layout__body tr').each(function () {
        let exclusive_item_count = $(".cf-desktop-grid .exclusive_item").length;
        let $parent = $(this);
        let $elemtToReverse = $(this).find('td');
        reverse_grid_s_order($parent, $elemtToReverse, exclusive_item_count)
    })

    //mobile
    //revered order
    let answerLists = $(".cf-mobile-grid-layout .cf-mobile-grid-layout__answer-content .cf-list")
    answerLists.css("flex-direction", "column-reverse")

    let answerListParent = $(".cf-mobile-grid-layout .cf-mobile-grid-layout__answer-content")
    answerListParent.each(function () {
        $(this).find('.cf - list__item').eq(-1).css('order', -1*exclusive_item_count-1)
        $(this).find('.cf - list__item').eq(-2).css('order', -1*exclusive_item_count)
    })

}
}


    
function reverse_grid_s_order(parent_elem,child_elem,fixitemCount)
{
    let remaining 
    if (fixitemCount > 0) {
    // Separate last two element
     remaining = child_elem.slice(0, fixitemCount*-1); 
    }
    else
    {
     remaining = child_elem
    }
    // Reverse and re-append only the remaining elements
    remaining.toArray().reverse().forEach(th => parent_elem.append(th));
     
    if (fixitemCount>0){
        let lastTwo = child_elem.slice(fixitemCount * -1);
        // Re-append last two elements to preserve their original order
        lastTwo.each((_, th) => parent_elem.append(th));
    }


}

