 	}
 }

 .exclusive_codes {
 	color: #656565;
 	/*font-style: italic;  optional */
 }

 /*Project specific customisation below (name initial)

 /* Base callout/card */
.vista-callout {
    margin: 24px 0;
    padding: 16px 20px;

    background: rgba(255, 255, 255, 0.55);
    border-left: 4px solid #075D5F;
    border-radius: 4px;

    font-size: 16px;
    line-height: 1.45;
}

/* Slightly stronger version for important status information */
.vista-callout--prominent {
    padding: 20px 24px;
    border-left-width: 5px;
}

/* Compact version for secondary/supporting information */
.vista-callout--compact {
    padding: 12px 16px;
}

/* Remove default paragraph spacing inside callouts */
.vista-callout p {
    margin: 0;
}

.vista-callout p + p {
    margin-top: 8px;
}

/* Small introductory/status label */
.vista-callout__label {
    margin-bottom: 4px;

    font-size: 17px;
    font-weight: 600;
    line-height: 1.4;
}

/* Main piece of information */
.vista-callout__value {
    font-size: 30px;
    font-weight: 700;
    line-height: 1.2;
}

/* Supporting explanatory text */
.vista-callout__note {
    margin-top: 8px;

    font-size: 16px;
    line-height: 1.4;
}

/* Inline heading within a smaller callout */
.vista-callout__heading {
    font-weight: 700;
}

/* Links inside callouts */
.vista-callout a {
    font-weight: 600;
}

/* This is to get the text box (which normally is flush with the text)
	to look the same as the radio buttons below
 */
#NO_OF_ADULTS_content {
	padding-left: 32px;
}

@media(max-width: 1024px) {
    #NO_OF_ADULTS_content {
        padding-left: 24px;
    }
}

@media(max-width: 480px) {
    #NO_OF_ADULTS_content {
        padding-left: 18px;
    }
}

Script.ScriptCode:
function runTimestampUpdate() {
  debugPrint("=== runTimestampUpdate() start ===");
  const date = new Date();
  const localTime = new Date(getDateInTZs(date).AEST);
  const localTimeString = formatTimestamp(localTime);
  debugPrint(`Local time string: ${localTimeString}`);

  const GLOBAL_TIMESTAMP = "total";

  // despite being passed through as a 'server variable' client side, it is retrieved
  // in the request form server side
  let pageTimeRaw;
  let pageTime;
  try {
    pageTimeRaw = Request.Form.Get("pageTime");
    debugPrint(`Raw pageTime from request: ${pageTimeRaw}`);
    pageTimeRaw = JSON.parse(pageTimeRaw);
    pageTime = pageTimeRaw.activeSeconds || "0";
  } catch {
    // defensive handling in case something goes wrong parsing the JSON payload
    pageTime = "0";
    pageTimeRaw = null;
  }

  // updates the questionnaire timings object for backend consumption
  updateQuestionTimingsJson(pageTimeRaw, date);

  pageTime = Number.parseInt(pageTime, 10);
  pageTime = Number.isNaN(pageTime) ? 0 : pageTime;
  debugPrint(`Parsed pageTime: ${pageTime}`);

  const startTime = f("start_datetime");
  const endTime = f("end_datetime");
  const activeDuration = f("active_duration");

  const globalStartTime = startTime.item(GLOBAL_TIMESTAMP);
  const globalEndTime = endTime.item(GLOBAL_TIMESTAMP);
  const globalActiveDuration = activeDuration.item(GLOBAL_TIMESTAMP);

  debugPrint(
    `Global before update: start=${globalStartTime.get()} end=${globalEndTime.get()} active=${globalActiveDuration.get()}`,
  );

  // On the first page we set the global timestamp once and then never touch it again
  if (!hasValue(globalStartTime)) {
    debugPrint(`Setting global start time to ${localTimeString}`);
    globalStartTime.set(localTimeString);
  } else {
    debugPrint(`Global start time already set: ${globalStartTime.get()}`);
  }

  // Global end time always updated with the most recent page submission time
  debugPrint(`Setting global end time to ${localTimeString}`);
  globalEndTime.set(localTimeString);

  const newGlobalActiveDuration =
    (Number(globalActiveDuration.get()) || 0) + pageTime;
  debugPrint(
    `Updating global active duration: ${Number(globalActiveDuration.get()) || 0} + ${pageTime} = ${newGlobalActiveDuration}`,
  );
  globalActiveDuration.set(newGlobalActiveDuration);

  debugPrint("Updated global active duration");

  const sectionTracker = createTimestampSectionTracker();
  debugPrint("Initialised sections object");
  sectionTracker.updateFromPageSubmission(
    startTime,
    endTime,
    activeDuration,
    localTimeString,
    pageTime,
  );

  debugPrint("=== runTimestampUpdate() end ===");
}

function createTimestampSectionTracker() {
  const sectionStackQid = f("timestamp_section_stack");
  const lastRenderedSectionQid = f("last_rendered_timestamp_section");

  function getSectionStack() {
    if (!hasValue(sectionStackQid)) {
      debugPrint("timestamp_section_stack has no value; using empty stack []");
      return [];
    }

    const rawStack = sectionStackQid.get();
    debugPrint(`Raw timestamp_section_stack: ${rawStack}`);

    let stack;
    try {
      stack = JSON.parse(rawStack);
    } catch (e) {
      debugPrint(`ERROR parsing timestamp_section_stack JSON: ${rawStack}`);
      throw new Error("timestamp_section_stack does not contain valid JSON.");
    }

    if (!Array.isArray(stack)) {
      debugPrint(`ERROR timestamp_section_stack is not an array: ${rawStack}`);
      throw new Error("timestamp_section_stack must be a JSON array.");
    }

    const normalizedStack = stack.map(String);
    debugPrint(
      `Parsed timestamp_section_stack: [${normalizedStack.join(", ")}]`,
    );
    return normalizedStack;
  }

  return {
    getCurrentSection() {
      const stack = getSectionStack();
      const currentSection = stack.at(-1) ?? null;
      debugPrint(`getCurrentSection() -> ${currentSection}`);
      return currentSection;
    },

    getLastRenderedSection() {
      const lastRenderedSection = hasValue(lastRenderedSectionQid)
        ? String(lastRenderedSectionQid.get())
        : null;
      debugPrint(`getLastRenderedSection() -> ${lastRenderedSection}`);
      return lastRenderedSection;
    },

    hasCurrent() {
      const result = this.getCurrentSection() != null;
      debugPrint(`hasCurrent() -> ${result}`);
      return result;
    },

    hasLastRendered() {
      const result = this.getLastRenderedSection() != null;
      debugPrint(`hasLastRendered() -> ${result}`);
      return result;
    },

    hasMovedSection() {
      const currentSection = this.getCurrentSection();
      const lastRenderedSection = this.getLastRenderedSection();
      const result = currentSection !== lastRenderedSection;
      debugPrint(
        `hasMovedSection() -> ${result} (current=${currentSection}, lastRendered=${lastRenderedSection})`,
      );
      return result;
    },

    updateFromPageSubmission(startTime, endTime, activeDuration, timeString, pageTime) {
      debugPrint("--- timestampSections.update() start ---");

      const currentSection = this.getCurrentSection();
      const lastRenderedSection = this.getLastRenderedSection();

      debugPrint(
        `Section state before update: current=${currentSection}, lastRendered=${lastRenderedSection}, pageTime=${pageTime}, timeString=${timeString}`,
      );

      if (currentSection == null) {
        debugPrint("No current section; skipping section timestamp update.");
        debugPrint("--- timestampSections.update() end ---");
        return;
      }

      this.updateStartTime(startTime, currentSection, timeString);
      this.updateEndTime(
        endTime,
        lastRenderedSection,
        currentSection,
        timeString,
      );
      this.updateActiveDuration(activeDuration, lastRenderedSection, pageTime);
      this.sync(currentSection);

      debugPrint("--- timestampSections.update() end ---");
    },

    updateStartTime(startTime, currentSection, timeString) {
      const sectionStartTime = startTime.item(currentSection);
      debugPrint(
        `updateStartTime(): section=${currentSection}, existingStart=${sectionStartTime.get()}`,
      );

      // Start time is first ever entry into the section
      if (!hasValue(sectionStartTime)) {
        debugPrint(
          `Setting start time for section ${currentSection} to ${timeString}`,
        );
        sectionStartTime.set(timeString);
      } else {
        debugPrint(
          `Start time for section ${currentSection} already set: ${sectionStartTime.get()}`,
        );
      }
    },

    updateEndTime(endTime, lastRenderedSection, currentSection, timeString) {
      debugPrint(
        `updateEndTime(): lastRendered=${lastRenderedSection}, current=${currentSection}`,
      );

      // No prior rendered section means there is nothing to close yet
      if (lastRenderedSection == null) {
        debugPrint("No last rendered section; not updating end time.");
        return;
      }

      // End time is the first time the respondent leaves the section,
      // including backwards movement
      if (lastRenderedSection !== currentSection) {
        const sectionEndTime = endTime.item(lastRenderedSection);
        debugPrint(
          `Section change detected. Candidate end update for section ${lastRenderedSection}; existingEnd=${sectionEndTime.get()}`,
        );

        if (!hasValue(sectionEndTime)) {
          debugPrint(
            `Setting end time for section ${lastRenderedSection} to ${timeString}`,
          );
          sectionEndTime.set(timeString);
        } else {
          debugPrint(
            `End time for section ${lastRenderedSection} already set: ${sectionEndTime.get()}`,
          );
        }
      } else {
        debugPrint("Still in same section; no end time update required.");
      }
    },

    updateActiveDuration(activeDuration, lastRenderedSection, add) {
      debugPrint(
        `updateActiveDuration(): lastRendered=${lastRenderedSection}, add=${add}`,
      );

      // The submitted page time belongs to the section of the page that was just rendered,
      // not necessarily the section currently being rendered now
      if (lastRenderedSection == null) {
        debugPrint("No last rendered section; not updating active duration.");
        return;
      }

      const sectionActiveDuration = activeDuration.item(lastRenderedSection);
      const currentValue = Number(sectionActiveDuration.get()) || 0;
      const increment = Number(add) || 0;
      const newValue = currentValue + increment;

      debugPrint(
        `Updating active duration for section ${lastRenderedSection}: ${currentValue} + ${add} = ${newValue}`,
      );
      debugPrint(
        `Active duration calc: (${typeof currentValue}) ${currentValue} + (${typeof increment}) ${increment} = ${newValue}`,
      );
      sectionActiveDuration.set(newValue);
    },

    sync(currentSection) {
      debugPrint(
        `sync(): setting last_rendered_timestamp_section to ${currentSection}`,
      );
      lastRenderedSectionQid.set(currentSection);
    },
  };
}

function setTimestampSection(sectionNumber) {
  debugPrint(`=== setTimestampSection(${sectionNumber}) start ===`);

  const sectionStackQid = f("timestamp_section_stack");
  const visitCount = f("visit_count");

  const rawStack = hasValue(sectionStackQid) ? sectionStackQid.get() : null;

  debugPrint(`Raw stored stack before update: ${rawStack}`);

  const sectionStack = hasValue(sectionStackQid)
    ? JSON.parse(sectionStackQid.get())
    : [];

  debugPrint(`Parsed stack before update: [${sectionStack.join(", ")}]`);

  const nextSection = String(sectionNumber);
  const validSections = visitCount.domainValues();

  debugPrint(`Requested next section: ${nextSection}`);
  debugPrint(`Valid timestamp sections: [${validSections.join(", ")}]`);

  if (!validSections.includes(nextSection)) {
    debugPrint(`ERROR invalid timestamp section: ${nextSection}`);
    throw new Error(`'${nextSection}' is not a valid timestamp section value.`);
  }

  const currentSection = sectionStack.at(-1);
  let newCurrentSection;

  debugPrint(`Current stack top before update: ${currentSection}`);

  if (nextSection === currentSection) {
    // Crossing the same boundary again means moving backwards
    debugPrint(
      `nextSection (${nextSection}) matches current stack top; interpreting as backwards movement and popping stack`,
    );
    sectionStack.pop();
    newCurrentSection = sectionStack.at(-1);
  } else {
    // New boundary crossing means moving forwards
    debugPrint(
      `nextSection (${nextSection}) differs from current stack top (${currentSection}); interpreting as forwards movement and pushing onto stack`,
    );
    sectionStack.push(nextSection);
    newCurrentSection = nextSection;
  }

  debugPrint(`Stack after update: [${sectionStack.join(", ")}]`);
  debugPrint(`New current section after stack update: ${newCurrentSection}`);

  sectionStackQid.set(JSON.stringify(sectionStack));
  debugPrint(`Persisted stack JSON: ${JSON.stringify(sectionStack)}`);

  // Stack empty means we are earlier than the first section
  if (newCurrentSection == null) {
    debugPrint(
      "New current section is null/undefined; no visit count updated because we are before the first section.",
    );
    debugPrint(`=== setTimestampSection(${sectionNumber}) end ===`);
    return;
  }

  const currentSectionVisitCount = visitCount.item(String(newCurrentSection));
  const currentVisitCountValue = Number(currentSectionVisitCount.get()) || 0;
  const newVisitCountValue = currentVisitCountValue + 1;

  debugPrint(
    `Updating visit count for section ${newCurrentSection}: ${currentVisitCountValue} + 1 = ${newVisitCountValue}`,
  );
  currentSectionVisitCount.set(newVisitCountValue);

  debugPrint(`=== setTimestampSection(${sectionNumber}) end ===`);
}

function debugPrint(msg) {
  if (false && !IsInProductionMode()) {
    Response.Write(msg + "<br>");
  }
}

function printTimestamps() {
  debugPrint("=== printTimestamps() start ===");

  const startTime = f("start_datetime");
  const endTime = f("end_datetime");
  const activeDuration = f("active_duration");
  const visitCount = f("visit_count");
  const sectionStackQid = f("timestamp_section_stack");
  const lastRenderedSectionQid = f("last_rendered_timestamp_section");

  debugPrint(
    `Current stored stack: ${hasValue(sectionStackQid) ? sectionStackQid.get() : "(empty)"}`,
  );
  debugPrint(
    `Last rendered section: ${hasValue(lastRenderedSectionQid) ? lastRenderedSectionQid.get() : "(empty)"}`,
  );

  const sections = startTime.domainValues();
  for (const section of sections) {
    debugPrint(
      `Section ${section}: ` +
        `Start ${startTime.item(section).get()} ` +
        `End ${endTime.item(section).get()} ` +
        `Active ${activeDuration.item(section).get()} ` +
        `Visits ${visitCount.item(section).get()}`,
    );
  }

  debugPrint("=== printTimestamps() end ===");
}

function hasValue(qid) {
  const value = qid.toBoolean();
  return value;
}

function melbourneUtcOffsetMinutes(instant = new Date()) {
  const t = instant instanceof Date ? instant.getTime() : Number(instant);
  if (!Number.isFinite(t)) {
    throw new TypeError("instant must be a Date or epoch milliseconds");
  }

  const d = new Date(t);
  const y = d.getUTCFullYear();
  const m = d.getUTCMonth(); // 0=Jan ... 11=Dec

  function firstSundayDayOfMonth(year, monthIndex) {
    const first = new Date(Date.UTC(year, monthIndex, 1, 0, 0, 0));
    const dow = first.getUTCDay(); // 0=Sun ... 6=Sat
    const delta = (7 - dow) % 7;
    return 1 + delta;
  }

  // first Sunday Oct at 02:00 AEST => previous day 16:00 UTC
  function dstStartUtcMillis(year) {
    const firstSundayOct = firstSundayDayOfMonth(year, 9);
    return Date.UTC(year, 9, firstSundayOct - 1, 16, 0, 0);
  }

  // first Sunday Apr at 03:00 AEDT => previous day 16:00 UTC
  function dstEndUtcMillis(year) {
    const firstSundayApr = firstSundayDayOfMonth(year, 3);
    return Date.UTC(year, 3, firstSundayApr - 1, 16, 0, 0);
  }

  let start;
  let end;

  if (m >= 9) {
    start = dstStartUtcMillis(y);
    end = dstEndUtcMillis(y + 1);
  } else {
    start = dstStartUtcMillis(y - 1);
    end = dstEndUtcMillis(y);
  }

  const isDst = t >= start && t < end;
  return isDst ? 11 * 60 : 10 * 60;
}

function getDateInTZs(dateObject) {
  const date = new Date(dateObject);
  const tzOffsetMs = melbourneUtcOffsetMinutes(date) * 60 * 1000;
  const ausDate = new Date(date.getTime() + tzOffsetMs);

  return {
    UTC: date.toLocaleString("en-AU"),
    AEST: ausDate.toLocaleString("en-AU"),
  };
}

function getDateStringAEST(date = new Date()) {
  const dateWithTZ = getDateInTZs(date);
  return new Date(dateWithTZ.AEST).toString();
}

function formatTimestamp(date = new Date()) {
  const pad = (n) => String(n).padStart(2, "0");

  const year = date.getFullYear();
  const month = pad(date.getMonth() + 1);
  const day = pad(date.getDate());
  const hours = pad(date.getHours());
  const minutes = pad(date.getMinutes());
  const seconds = pad(date.getSeconds());

  return `${year}-${month}-${day} ${hours}:${minutes}:${seconds}`;
}

// our best effort attempt at keeping a record of per-question submission times. 
function updateQuestionTimingsJson(timingsObject, runTime) {
  if (!isNonEmptyObject(timingsObject)) {
    return;
  }

  const questionTimings = f("question_timings_json");
  if (!hasValue(questionTimings)) {
    questionTimings.set(JSON.stringify([]));
  }

  try {
    const questionTimingsObj = JSON.parse(questionTimings.get());
    timingsObject = {
      ...timingsObject,
      submitTime: runTime,
    };

    questionTimingsObj.push(timingsObject);
    questionTimings.set(JSON.stringify(questionTimingsObj));
  } finally {}
}

function isNonEmptyObject(value) {
  return (
    value !== null &&
    typeof value === "object" &&
    !Array.isArray(value) &&
    Object.keys(value).length > 0
  );
}

