// [WG] [EXPLAIN] when to use this function?
/**
 * Copy selected values from one grid to another.
 */
function copytogridcombined(to,fr) {
    var prec = f(fr).domainValues(); 

    for (var i = 0; i < prec.length; i++) {
        var code = prec[i];
        if (f(fr).item(code).toBoolean()) {
            f(to).item(code).set(f(fr).item(code).get());
        }
    }
}

// [WG] [EXPLAIN] is this still in use? when to use?
/**
 * add to custom validation for all JavaScript DK/REF questions
 */
function setDKREF() {
  const qnIndex = String(a("qn_dkref"))
    .split(",")
    .map(s => s.trim())
    .filter(s => s.length > 0)
    .map(Number)
    .filter(Number.isFinite);

  const qnIndexSort = [...qnIndex].sort((a, b) => a - b);

  // Clear existing DK/REF flags for current question
  qnIndexSort.forEach(val => {
      if (f("qn_dkref_" + val + "_other").get() == CurrentForm()) {
          f("qn_dkref_" + val).set(null);
          f("qn_dkref_" + val + "_other").set(null);
      }
  });

  // Set if question is DK/REF
  const getnrv = f(CurrentForm()).getNoResponseValue();
  if (getnrv != null) {
    for (let val of qnIndexSort) {
      if (!f("qn_dkref_" + val + "_other").toBoolean()) {
        f("qn_dkref_" + val).set(getnrv);
        f("qn_dkref_" + val + "_other").set(CurrentForm());
        break;
      }
    }
  }
}

function getProjectSettings(name) {
  const projectSettings = {
    // This might not be the same as the src_job_id. 
    // If you need to dedupe across multiple separate Forsta surveys, you would set them
    // all to have the same value below
    DEDUPE_PROJECT_CODE: "SRCXXXX",
    // set as a single string, NO spaces
    //e.g. LinA, ORU, Octopus, Pureprofile, Lightspeed, Open (for open link), Client
    PANEL_NAME: f('panel_name').toBoolean()?f('panel_name'):'LinA',
    // Set the country code for where the survey is running. Is used by RD to detect country mismatches and 
    // block respondents for entering the survey
    // NZ for New Zealand etc (Can only set to one single country)
    COUNTRY_CODE: "AU",
    // Controls whether the screen containing Research Defender is automatically submitted
    // once the API queries have completed or the timeout is reached, whichever happens first.
    //
    // Useful when Research Defender is placed on an intermediate screen and respondents
    // should continue automatically without clicking Next.
    AUTO_SUBMIT: true,
  };
  return projectSettings[name];
}

/*
  Uncomment the relevant config below, appropriate for the sample source being used for the project.
  Currently supported types are:
    - LinA
    - Client sample with/without incentives
    - Non-probability panel / MMM / Polaron
    - Commercial list sample with/without incentives
    - A-BS push-to-web
    - RDD SMS push-to-web
    - Open link / social media **WITHOUT** incentives
    - Open link / social media **WITH** incentives
*/

// - LinA
// - Client sample with/without incentives
