// Function which can be used for debugging server side scripts. 
// Print statements can be left in and won't be accidentally leaked to the respondent.
function debugPrint(msg) {
    if (!IsInProductionMode()) {
     //   Response.Write(msg + "<br>");
    }
}

// Used for hashing the API query and verifying integrity of the response retrieved from the API
// This code lives here: https://github.com/socialresearchcentre/forsta-sha256

function sha256(input) {
  // --- helpers ---
  function rrot(x, n) { return (x >>> n) | (x << (32 - n)); }
  function toHex(n) {
    n >>>= 0;
    var s = n.toString(16);
    return "00000000".slice(s.length) + s;
  }
  function toBytes(msg) {
    if (msg == null) throw new Error("sha256: null/undefined input");
    // Uint8Array / ArrayBuffer / array of numbers
    if (typeof msg !== "string") {
      if (msg instanceof Uint8Array) return Array.prototype.slice.call(msg);
      if (msg && msg.buffer instanceof ArrayBuffer) {
        return Array.prototype.slice.call(new Uint8Array(msg.buffer, msg.byteOffset || 0, msg.byteLength || msg.length));
      }
      if (Array.isArray(msg)) return msg.slice();
      throw new Error("sha256: unsupported non-string input");
    }
    // UTF-8 encode string (surrogate-safe)
    var bytes = [];
    for (var i = 0; i < msg.length; i++) {
      var c = msg.charCodeAt(i);
      if (c < 0x80) {
        bytes.push(c);
      } else if (c < 0x800) {
        bytes.push(0xC0 | (c >>> 6), 0x80 | (c & 0x3F));
      } else if (c >= 0xD800 && c <= 0xDBFF) { // surrogate pair
        var c2 = msg.charCodeAt(++i);
        var cp = ((c & 0x3FF) << 10) + (c2 & 0x3FF) + 0x10000;
        bytes.push(0xF0 | (cp >>> 18), 0x80 | ((cp >>> 12) & 0x3F),
                   0x80 | ((cp >>> 6) & 0x3F), 0x80 | (cp & 0x3F));
      } else {
        bytes.push(0xE0 | (c >>> 12), 0x80 | ((c >>> 6) & 0x3F), 0x80 | (c & 0x3F));
      }
    }
    return bytes;
  }

  var K = [
    0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,
    0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,
    0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,
    0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,
    0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,
    0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,
    0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,
    0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2
  ];

  var h0 = 0x6a09e667, h1 = 0xbb67ae85, h2 = 0x3c6ef372, h3 = 0xa54ff53a;
  var h4 = 0x510e527f, h5 = 0x9b05688c, h6 = 0x1f83d9ab, h7 = 0x5be0cd19;

  var bytes = toBytes(input);
  var originalLen = bytes.length;

  // Padding: append 0x80, then zeros, then 64-bit big-endian length (in bits)
  bytes.push(0x80);
  while ((bytes.length % 64) !== 56) bytes.push(0);
  var bitLenHi = Math.floor(originalLen / 0x20000000) >>> 0; // floor(len*8 / 2^32)
  var bitLenLo = (originalLen << 3) >>> 0;                    // (len*8) mod 2^32
  bytes.push((bitLenHi >>> 24) & 0xFF, (bitLenHi >>> 16) & 0xFF, (bitLenHi >>> 8) & 0xFF, bitLenHi & 0xFF,
             (bitLenLo >>> 24) & 0xFF, (bitLenLo >>> 16) & 0xFF, (bitLenLo >>> 8) & 0xFF, bitLenLo & 0xFF);

  var w = new Array(64);

  for (var i = 0; i < bytes.length; i += 64) {
    for (var j = 0; j < 16; j++) {
      var idx = i + j * 4;
      w[j] = ((bytes[idx] << 24) | (bytes[idx + 1] << 16) | (bytes[idx + 2] << 8) | (bytes[idx + 3])) >>> 0;
    }
    for (var j = 16; j < 64; j++) {
      var s0 = (rrot(w[j - 15], 7) ^ rrot(w[j - 15], 18) ^ (w[j - 15] >>> 3)) >>> 0;
      var s1 = (rrot(w[j - 2], 17) ^ rrot(w[j - 2], 19) ^ (w[j - 2] >>> 10)) >>> 0;
      w[j] = (w[j - 16] + s0 + w[j - 7] + s1) >>> 0;
    }

    var a = h0, b = h1, c = h2, d = h3, e = h4, f = h5, g = h6, h = h7;

    for (var j = 0; j < 64; j++) {
      var S1 = (rrot(e, 6) ^ rrot(e, 11) ^ rrot(e, 25)) >>> 0;
      var ch = ((e & f) ^ ((~e) & g)) >>> 0;
      var T1 = (h + S1 + ch + K[j] + w[j]) >>> 0;
      var S0 = (rrot(a, 2) ^ rrot(a, 13) ^ rrot(a, 22)) >>> 0;
      var maj = ((a & b) ^ (a & c) ^ (b & c)) >>> 0;
      var T2 = (S0 + maj) >>> 0;

      h = g; g = f; f = e;
      e = (d + T1) >>> 0;
      d = c; c = b; b = a;
      a = (T1 + T2) >>> 0;
    }

    h0 = (h0 + a) >>> 0;
    h1 = (h1 + b) >>> 0;
    h2 = (h2 + c) >>> 0;
    h3 = (h3 + d) >>> 0;
    h4 = (h4 + e) >>> 0;
    h5 = (h5 + f) >>> 0;
    h6 = (h6 + g) >>> 0;
    h7 = (h7 + h) >>> 0;
  }

  return toHex(h0) + toHex(h1) + toHex(h2) + toHex(h3) +
         toHex(h4) + toHex(h5) + toHex(h6) + toHex(h7);
}

// This generates the ID passed to the RD api. 
// RD documentation specifies that this must be globally unique.
function getUniqueID() {
  const surveyId = CurrentPID();
  const respondentId = CurrentID();
  const responseId = GetResponseId();

  const uniqueResponseId = [surveyId, respondentId, responseId].join("-");
  return uniqueResponseId;
}

// uses V4 of the search API which allows for 'signing' the query before it is passed to the 
// API which prevents the respondent from tampering with the query.
function makeRDSearchURL() {

  // This might not be the same as the survey Id if you need to dedupe across multiple surveys.
  // See documentation in consts script.
  const dedupeSurveyNumber = getDedupeSurveyNumber();
  const uniqueResponseId = getUniqueID();

  const publicKey = getSearchPublicKey();
  const privateKey = getSearchPrivateKey();

  const countryCode = getCountryCode();

  let searchURL = "https://prod.rtymgt.com/api/v4/respondents/search/" +
    publicKey +
    "?sy_nr=" + encodeURIComponent(dedupeSurveyNumber) +
    "&sn_ud=" + encodeURIComponent(uniqueResponseId) +
    "&rt_cy_ce=" + encodeURIComponent(countryCode);

  const panelName = getPanelName();
  if (panelName) {
    searchURL += "&pm_sr_id=" + encodeURIComponent(panelName);
  }

  const hash = sha256(searchURL + privateKey);
  const hashedURL = searchURL + "&validation=" + hash;

  return hashedURL;
}    

// This endpoint does not support signing the URL. Instead they offer the solution 
// where we generate a token on the client side, when they pass back to us and we 
// retrieve the result from RD directly, which bypasses the possibility of client tampering.
// See readme
function makeRDActivityURL() {
  const dedupeSurveyNumber = getDedupeSurveyNumber();
  const uniqueResponseId = getUniqueID();

  const activityURL = "https://prod.resdefio.com/activity" +
    "?survey_number=" + encodeURIComponent(dedupeSurveyNumber) +
    "&session_id=" + encodeURIComponent(uniqueResponseId);

  return activityURL;
}

function makeTokenURL() {
  return "https://prod.resdefio.com/token";
}

Multi.StartupScript:
window.addEventListener("DOMContentLoaded", async () => {
  // determines how long to wait for API response before timeing out
  const TIMEOUT = "^getTimeout()^";
  const SEARCH_ENDPOINT = "^makeRDSearchURL()^";
  const EVENT_NAME = "^getSearchEventName()^";

  const RD_DELAY_MS = 100;
  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

  // helper function to trigger the right event
  function triggerEvent(target, eventType) {
    let el = target || document;
    el.dispatchEvent(
      new CustomEvent(eventType, { bubbles: true }),
    );
  }

  async function getRdPassParamsSafely() {
    // This is the name of the globalThis object we define in the <script> module import
    // in the OnlineIntro html
    const RD = globalThis.RD; 

    const start = performance.now();
    while (!RD || typeof RD.pass_params !== "function" || (performance.now() < (start + 1000 * 5))) {
      console.log("Waiting for RD.pass_params()");
      await sleep(100);
    }

    // waited 5 seconds and function still wasn't available
    if (!RD || typeof RD.pass_params !== "function" ) {
      console.log("RD module not available (pass_params missing).");
      return null;
    }

    // there is some async code in pass_params() according to the documentation that 
    // research defender suggests waiting 100 ms before reading the values
    await sleep(RD_DELAY_MS);

    try {
      return RD.pass_params();
    } catch (err) {
      console.log("pass_params() failed:", err);
      return null;
    }
  }

  try {
    const divSearch = document.getElementById("RD_Search");
    const question = currentQuestion;
    if (!divSearch) {
      console.log("Could not find #`RD_Search`. Check the name of the node.");
      return;
    }

    if (!question) {
      console.log("Could not find `currentQuestion`.");
      return;
    }

    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), TIMEOUT);

    let resp;
    try {
      let url = SEARCH_ENDPOINT;

      resp = await fetch(url, {
        method: "GET",
        credentials: "include",
        headers: { Accept: "application/json" },
        signal: controller.signal,
      });
    } finally {
      clearTimeout(timeoutId);
    }

    // The order of writing to the form is important because the Intro screen script checks that the status code 
    // has been filled in to determine if this has finished executing (assuming that it runs after the API getting code)

    // write the raw API response to the form
    const text = await (resp ? resp.text() : Promise.resolve(""));
    const rawEl = document.getElementById("RD_Search_raw_response");
    if (rawEl) rawEl.value = text;
    question.setValue("raw_response", text);

    // write the status code to the form
    const status = resp ? resp.status : 0;
    const statusEl = document.getElementById("RD_Search_status_code_input");
    if (statusEl) statusEl.value = status;
    question.setValue("status_code", status);

    triggerEvent(divSearch, EVENT_NAME);
    return;
  } catch (e) {
    triggerEvent(null, EVENT_NAME);
    console.log(e);
  }
});

window.addEventListener("DOMContentLoaded", async () => {
