    console.log(e);
  }
});

Info.StartupScript:
window.addEventListener("DOMContentLoaded", async () => {
  // Helper: one-shot event wait that resolves immediately if already filled
  const waitReady = (type, { precheck } = {}) => {
    if (precheck?.()) {
      return Promise.resolve({ detail: { ok: true, prefilled: true } });
    }

    return new Promise((resolve) => {
      const handler = (e) => resolve(e);
      document.addEventListener(type, handler, { once: true });
    });
  };

  // Prefill checks handle cases where producers ran before this script
  const searchPrefilled = () => {
    const s = document.getElementById("RD_Search_status_code_input");
    return !!(s && String(s.value).trim() !== "");
  };
  const activityPrefilled = () => {
    const a = document.getElementById("RD_Activity_status_code_input");
    return !!(a && String(a.value).trim() !== "");
  };

  await Promise.all([
    waitReady("^getSearchEventName()^", { precheck: searchPrefilled }),
    waitReady("^getActivityEventName()^", { precheck: activityPrefilled }),
  ]);

  const waitingMessage = document.getElementById("RDwaitingMessage");
  const introMessage = document.getElementById("RDintroMessage");
  const introInstruction = document.getElementById("RD_introInstruction");

  if (waitingMessage) waitingMessage.hidden = true;
  if (introMessage) introMessage.hidden = false;
  if (introInstruction) introInstruction.hidden = false;

  document.documentElement.classList.remove('rd-loading');

  if ("^getProjectSettings('AUTO_SUBMIT')^".toLowerCase() === "true") {
    document.querySelector('.cf-navigation-next')?.click();
  }
});

Script.ScriptCode:
processSearchResults();
processActivityResults();
determineOverallPassFail();
// ------------------------------------------------------------------

// Determines the overall Research Defender outcome by merging the tri-state
// results from the search and activity checks. Any "1" from either branch wins,
// an indeterminate "-1" bubbles up when no branch fails but at least one is
// unresolved, and only dual "0" values produce a pass.
function determineOverallPassFail() {
  const searchQuestion = f("RD_Search");
  const activityQuestion = f("RD_Activity");

  const searchResult = searchQuestion.item("fail").valueOf();
  const activityResult = activityQuestion.item("fail").valueOf();

  let overallResult;

  if (searchResult === "1" || activityResult === "1") {
    overallResult = "1";
  } else if (searchResult === "-1" || activityResult === "-1") {
    overallResult = "-1";
  } else {
    overallResult = "0";
  }

  f("research_defender_fail").set(overallResult);
}

// Processes the SEARCH API results to determine an overal pass/fail.
function processSearchResults() {
  const FAIL_ON_API_ERROR = getRDConfig("FAIL_ON_API_ERROR");

  const searchQuestion = f("RD_Search");
  // default is to fail
  setFailItem(searchQuestion, "1");

  const statusCode = searchQuestion.item("status_code").valueOf();
  const rawResponse = searchQuestion.item("raw_response").valueOf();

  // API request failed.
  if (statusCode !== "200") {
    const errorMsg = "API HTTP Error: " + statusCode;
    if (FAIL_ON_API_ERROR) {
      setFinalFailReason(searchQuestion, errorMsg);
    } else {
      setIndeterminateResult(searchQuestion, errorMsg);
    }
    return;
  }

  // As above, if the response is empty we either fail or set indeterminate
  if (!rawResponse) {
    const errorMsg = "Successful HTTP response but empty body";
    if (FAIL_ON_API_ERROR) {
      setFinalFailReason(searchQuestion, errorMsg);
    } else {
      setIndeterminateResult(searchQuestion, errorMsg);
    }
    return;
  }

  let response;
  try {
    response = JSON.parse(rawResponse);
  } catch (e) {
    // If parsing fails, then something has gone wrong with the API response.
    // Either the API has returned an invalid object (unlikely) or the response has been
    // corrupted/tampered with
    const errorMsg = "Failed to parse JSON response: " + e.message;
    if (FAIL_ON_API_ERROR) {
      setFinalFailReason(searchQuestion, errorMsg);
    } else {
      setIndeterminateResult(searchQuestion, errorMsg);
    }
    return;
  }

  // V4 of the API returns these fields to allow for validating the integrity of the
  // API response
  let surveyValidationHash = response.Validation?.Surveys || null;
  let respondentValidationHash = response.Validation?.Respondent || null;

  // missing hashes suggests tampering. Respondent should fail
  if (!surveyValidationHash || !respondentValidationHash) {
    setFinalFailReason(searchQuestion, "Missing validation hashes in response");
    return;
  }

  const surveyString = response.String?.Surveys || null;
  const respondentString = response.String?.Respondent || null;

  if (!surveyString || !respondentString) {
    setFinalFailReason(
      searchQuestion,
      "Missing string representations in response",
    );
    return;
  }

  const isSurveyHashValid = verifyHash(surveyString, surveyValidationHash);
  const isRespondentHashValid = verifyHash(
    respondentString,
    respondentValidationHash,
  );

  if (!isSurveyHashValid || !isRespondentHashValid) {
    setFinalFailReason(
      searchQuestion,
      "Data integrity check failed, API response may have been tampered with",
    );
    return;
  }

  const surveysFields = [
    "sn_ud",
    "duplicate_potential",
    "failure_reason",
    "duplicate_score",
    "flag",
    "country_mismatch",
    "survey_number",
    "duplicate_initial_ud",
  ];

  const rdSurveyData = extractSurveyData(surveyString, surveysFields);
  updateQuestionItems(searchQuestion, rdSurveyData);

  const respondentFields = [
    "country",
    "country_code",
    "respondent_risk",
    "respondent_ud",
    "threat_potential",
    "threat_potential_score",
  ];

  const rdRespondentData = extractSurveyData(
    respondentString,
    respondentFields,
  );
  updateQuestionItems(searchQuestion, rdRespondentData);

  let shouldFail;
  try {
    shouldFail = shouldTerminate();
  } catch (e) {
    // Mark that the API response was malformed and let this person through.
    // Note that at this stage we have verified the API response has been signed
    // and has not been tampered with, so there is something wrong with the API 
    // repsonse (couldn't parse to Int etc.)
    setIndeterminateResult(
      searchQuestion,
      "Malformed API response: " + e.message,
    );
    return;
  }

  if (shouldFail) {
    setFinalFailReason(searchQuestion, "Failed Search checks");
  } else {
    setFailItem(searchQuestion, "0");
  }
}

// Contains the logic for whether a respondent should pass or fail the SEARCH API checks
// Thresholds can be adjusted and tests activated/deactivated in the RD Config
function shouldTerminate() {
  const searchQuestion = f("RD_Search");

  let threatPotentialScore = searchQuestion
    .item("threat_potential_score")
    .valueOf();
  let duplicateScore = searchQuestion.item("duplicate_score").valueOf();
  let countryMismatch = searchQuestion.item("country_mismatch").valueOf();

  threatPotentialScore = parseIntOrThrow(
    threatPotentialScore,
    "threat_potential_score",
  );
  duplicateScore = parseIntOrThrow(duplicateScore, "duplicate_score");
  countryMismatch = parseIntOrThrow(countryMismatch, "country_mismatch");

  const threatPotentialThresh = getRDConfig("THREAT_POTENTIAL_THRESHOLD");
  const duplicateScoreThresh = getRDConfig("DUPLICATE_SCORE_THRESHOLD");
  const countryMismatchCheck = getRDConfig("COUNTRY_MISMATCH_CHECK");


  let duplicateScoreFail =
    duplicateScoreThresh && duplicateScore >= duplicateScoreThresh;

  // There is an edge case where a respondent can trigger a duplicate score fail to themselves,
  // i.e. their sn_ud matches the duplicate_initial_ud. We should not fail them.
  const sn_id = searchQuestion.item("sn_ud").valueOf();
  const duplicate_initial_ud = searchQuestion
    .item("duplicate_initial_ud")
    .valueOf();

  if (duplicateScoreFail && !sn_id) {
    throw new Error(
      "threat_potential_score indicates fail but sn_ud is missing",
    );
  }

  if (duplicateScoreFail && !duplicate_initial_ud) {
    throw new Error(
      "threat_potential_score indicates fail but duplicate_initial_ud is missing",
    );
  }

  const isSelfDuplicate = sn_id === duplicate_initial_ud;
  duplicateScoreFail = duplicateScoreFail && !isSelfDuplicate;

  const threatPotentialFail =
    threatPotentialThresh && threatPotentialScore >= threatPotentialThresh;

  const countryFail = countryMismatchCheck && countryMismatch === 1;

  return threatPotentialFail || duplicateScoreFail || countryFail;
}

function parseIntOrThrow(value, fieldName) {
  const intValue = parseInt(value, 10);
  if (Number.isNaN(intValue)) {
    throw new Error(`Failed to parse ${fieldName} ("${value}") as integer`);
  }
  return intValue;
}

// Processes the ACTIVITY results and determines overall pass/fail
function processActivityResults() {
  const FAIL_ON_API_ERROR = getRDConfig("ACTIVITY_FAIL_ON_API_ERROR");
  const ACTIVITY_COUNT_THRESHOLD = getRDConfig("ACTIVITY_COUNT_THRESHOLD");

  const activityQuestion = f("RD_Activity");
  const statusCode = activityQuestion.item("status_code").valueOf();
  const rawResponse = activityQuestion.item("raw_token_response").valueOf();

  // default it to fail
  setFailItem(activityQuestion, "1");

  // see comments in processSearchResults about API failure logic.
  if (statusCode !== "200") {
    const errorMsg = "API HTTP Error: " + statusCode;
    if (FAIL_ON_API_ERROR) {
      setFinalFailReason(activityQuestion, errorMsg);
    } else {
      setIndeterminateResult(activityQuestion, errorMsg);
    }
    return;
  }

  if (!rawResponse) {
    const errorMsg = "Successful HTTP response but empty body";
    if (FAIL_ON_API_ERROR) {
      setFinalFailReason(activityQuestion, errorMsg);
    } else {
      setIndeterminateResult(activityQuestion, errorMsg);
    }
    return;
  }

  let parsedResponse;
  try {
    parsedResponse = JSON.parse(rawResponse);
  } catch (e) {
    const errorMsg = "Failed to parse JSON token response: " + e.message;
    if (FAIL_ON_API_ERROR) {
      setFinalFailReason(activityQuestion, errorMsg);
    } else {
      setIndeterminateResult(activityQuestion, errorMsg);
    }
    return;
  }

  const token = parsedResponse?.Results?.[0]?.Tokens?.[0] || null;
  if (!token) {
    const errorMsg = "No token found in API response";
    if (FAIL_ON_API_ERROR) {
      setFinalFailReason(activityQuestion, errorMsg);
    } else {
      setIndeterminateResult(activityQuestion, errorMsg);
    }
    return;
  }

  const activityURL = makeRDActivityURL();
  const headers = {
    "Content-Type": "application/json",
    "Access-Control-Allow-Headers": "token",
    "x-api-key": getActivityPublicKey(),
    token: token,
  };

  let resp;

  try {
    resp = Http.Get(activityURL, null, headers);
  } catch (e) {
    const errorMsg = "Failed to fetch activity data: " + e.message;
    if (FAIL_ON_API_ERROR) {
      setFinalFailReason(activityQuestion, errorMsg);
    } else {
      setIndeterminateResult(activityQuestion, errorMsg);
    }
    return;
  }

  // we only have access to the body as text
  // if empty, then an unknown error
  if (!resp) {
    const errorMsg = "Empty body returned from activity endpoint";
    if (FAIL_ON_API_ERROR) {
      setFinalFailReason(activityQuestion, errorMsg);
    } else {
      setIndeterminateResult(activityQuestion, errorMsg);
    }
    return;
  }

  activityQuestion.item("raw_response").set(resp);

  let respJson;
  try {
    respJson = JSON.parse(resp);
  } catch (e) {
    setIndeterminateResult(
      activityQuestion,
      "Failed to parse JSON activity response: " + e.message,
    );
    return;
  }

  const message = respJson?.message || null;

  if (message && message.toLowerCase() === "this token has already been used") {
    const errorMsg = "Respondent supplied a reused token";
    // We don't want to fail on this if we are not failing on API errors. When everything in the 
    // config is set to false, we shouldn't fail anyone, so need to be able to disable these one.
    if (FAIL_ON_API_ERROR) {
      setFinalFailReason(activityQuestion, errorMsg);
    } else {
      setIndeterminateResult(activityQuestion, errorMsg);
    }
    return;
  }

  if (message && message.toLowerCase() === "this token does not exist") {
    const errorMsg = "Respondent supplied an invalid token";
    if (FAIL_ON_API_ERROR) {
      setFinalFailReason(activityQuestion, errorMsg);
    } else {
      setIndeterminateResult(activityQuestion, errorMsg);
    }
    return;
  }

  const statistics = respJson?.Statistics?.[0]?.Activity?.Token;

  if (!statistics) {
    setIndeterminateResult(
      activityQuestion,
      "No statistics found in activity response",
    );
    return;
  }

  const statsToExtract = [
    "Count",
    "Average",
    "Ratio",
    "Median",
    "StandardDeviation",
  ];

  for (const stat of statsToExtract) {
    const value = statistics[stat] ?? null;
    activityQuestion.item(stat).set(value);
  }

  const count = statistics["Count"] ?? null;
  if (count === null) {
    setIndeterminateResult(
      activityQuestion,
      "No Count found in activity statistics",
    );
    return;
  }

  const countInt = parseInt(count, 10);
  if (Number.isNaN(countInt)) {
    setIndeterminateResult(
      activityQuestion,
      `Failed to parse Count "${count}" as integer`,
    );
    return;
  }

  if (ACTIVITY_COUNT_THRESHOLD && countInt >= ACTIVITY_COUNT_THRESHOLD) {
    setFinalFailReason(
      activityQuestion,
      "Respondent activity too high: " + countInt,
    );
    return;
  }

  setFailItem(activityQuestion, "0");
}

// helper to extract the API response from the invalid JSON string.
function extractSurveyData(surveysString, fieldsToExtract) {
  let extractedData = {};
  for (const v of fieldsToExtract) {
    const regex = new RegExp(`${v}:([^,}\\]]+)`);
    const match = surveysString.match(regex);
    if (match && match[1]) {
      extractedData[v] = match[1];
    }
  }

  return extractedData;
}

// helper to update MR text questions
function updateQuestionItems(question, data) {
  for (const v in data) question.item(v).set(data[v]);
}

function setFinalFailReason(question, reason) {
  question.item("final_fail_reason").set(reason);
}

function setFailItem(question, failValue) {
  question.item("fail").set(failValue);
}

function setIndeterminateResult(question, reason) {
  setFinalFailReason(question, reason);
  setFailItem(question, "-1");
}

// Verfies that the hash and string returned from the API match
function verifyHash(dataString, expectedHash) {
  const privateKey = getSearchPrivateKey();
  const computedHash = sha256(dataString + privateKey);
  return computedHash === expectedHash;
}

