function isSingleHH() {
  const nAdults = f("NO_OF_ADULTS").get();
  const noChildrenOption = f("NO_OF_CHILDREN").get() == "2";
  const noChildrenOther =
    (f("NO_OF_CHILDREN").get() == "1" &&
      // other box only allows strings of the form \d\d
      f("NO_OF_CHILDREN_1_other").get() == "0") ||
    f("NO_OF_CHILDREN_1_other").get() == "00";
  const noChildren = noChildrenOption || noChildrenOther;
  const isSingle = nAdults == 1 && noChildren;
  return isSingle;
}

