Script.ScriptCode:
function vista_buildReturnSpec(forstaUrl) {
    var questionMarkIndex = forstaUrl.indexOf("?");

    if (questionMarkIndex === -1) {
        return {
            url: forstaUrl,
            params: {}
        };
    }

    var baseUrl = forstaUrl.substring(0, questionMarkIndex);
    var queryString = forstaUrl.substring(questionMarkIndex + 1);
    var params = {};

    var parts = queryString.split("&");

    for (var i = 0; i < parts.length; i++) {
        if (!parts[i]) {
            continue;
        }

        var equalsIndex = parts[i].indexOf("=");

        var key;
        var value;

        if (equalsIndex === -1) {
            key = parts[i];
            value = "";
        } else {
            key = parts[i].substring(0, equalsIndex);
            value = parts[i].substring(equalsIndex + 1);
        }

        params[decodeURIComponent(key)] = decodeURIComponent(value);
    }

    return {
        url: baseUrl,
        params: params
    };
}


forstaLogger("INFO", "Starting Logicly router");

// Need to do this before redirecting to avoid race conditions
vista_refreshCompletionStatus();

var VISTA_STATE = vista_getStates();
var resolvedState = vista_resolveState();

if (resolvedState !== VISTA_STATE.ACTIVE) {
    forstaLogger(
        "INFO",
        "Respondent is complete. Not redirecting to Logicly"
    );

    // User-base router
    vista_route();

} else {

    forstaLogger("INFO", "Redirecting respondent to Logicly");

    var config = vista_getConfig();

    /*
     * Let Forsta generate the complete respondent-specific return URL.
     *
     * The empty question ID causes the respondent to return to the
     * beginning of the survey, where the Start block can refresh the
     * authoritative state from Logicly and dispatch appropriately.
     */
    var forstaReturnUrl = GetRespondentUrl(
        "",
        false,
        "source=logicly"
    );

    forstaLogger(
        "INFO",
        "Generated Forsta return URL for Logicly: " +
        forstaReturnUrl
    );

    /*
     * Logicly expects the URL and its query parameters separately.
     * Do not make any assumptions here about Forsta using __sid__;
     * simply preserve whatever parameters Forsta generated.
     */
    var returnSpec = vista_buildReturnSpec(forstaReturnUrl);

    forstaLogger(
        "INFO",
        "Logicly return spec: " + JSON.stringify(returnSpec)
    );

    var logiclyURL;

    try {
        logiclyURL = vista_getParticipantUrl(
            config,
            config.projectId,
            f("logicly_id").get(),
            returnSpec
        );
    } catch (error) {
        forstaLogger(
            "ERROR",
            "Couldn't generate Logicly URL. Received error: " +
            error.message +
            ". Trying again"
        );

        try {
            logiclyURL = vista_getParticipantUrl(
                config,
                config.projectId,
                f("logicly_id").get(),
                returnSpec
            );
        } catch (error) {
            forstaLogger(
                "FATAL",
                "Was unable to generate Logicly URL a second time. " +
                "Received error: " +
                error.message
            );

            throw error;
        }
    }

    if (!logiclyURL) {
        forstaLogger(
            "FATAL",
            "Logicly URL generation failed for unknown reason"
        );

        throw new Error(
            "Logicly URL generation failed for unknown reason"
        );
    }

    forstaLogger(
        "INFO",
        "Got URL for Logicly: " + logiclyURL
    );

    Redirect(logiclyURL, true);
}

