          [],
        );
        emit(log, "INFO", "Get participant completed successfully");
        return participant;
      } catch (error) {
        var contextual = contextualError("get participant", error);
        emit(log, "ERROR", contextual.message);
        throw contextual;
      }
    }
    function getParticipantUrl(
      configInput,
      projectIdInput,
      participantIdInput,
      returnSpecInput,
    ) {
      try {
        var config = validateConfig(configInput);
        var projectId = requiredString(projectIdInput, "projectId");
        var participantId = requiredString(participantIdInput, "participantId");
        var returnSpec = validateReturnSpec(returnSpecInput);
        emit(
          log,
          "INFO",
          "Get participant URL started for project " +
          projectId +
          " and participant " +
          participantId,
        );
        var token = accessToken(config, http, log);
        var url = participantPath(config, projectId, participantId) + "/login";
        emit(log, "INFO", "Sending POST " + url);
        var response = http.post(
          url,
          {
            isAdmin: false,
            return: returnSpec,
          },
          authHeaders(token.value, true, config.userAgent),
        );
        var login = objectResponse(
          response,
          "Participant login endpoint",
          log,
          [],
        );
        var link = requiredString(login.link, "Participant login link");
        emit(log, "INFO", "Get participant URL completed successfully");
        return link;
      } catch (error) {
        var contextual = contextualError("get participant URL", error);
        emit(log, "ERROR", contextual.message);
        throw contextual;
      }
    }
    function diagnoseAccess(configInput) {
      try {
        var config = validateConfig(configInput);
        emit(log, "INFO", "Access diagnosis started");
        var token = accessToken(config, http, log);
        var diagnostic = inspectAccessToken(token, config);
        logTokenDiagnostic(log, diagnostic);
        var url = config.baseUrl + "/projects";
        emit(log, "INFO", "Sending authenticated access probe GET " + url);
        var response = http.get(
          url,
          void 0,
          authHeaders(token.value, false, config.userAgent),
        );
        var projects = parseJson(response, "Access probe endpoint", log, []);
        if (!Array.isArray(projects)) {
          emit(
            log,
            "ERROR",
            "Access probe returned JSON but not a project array",
          );
          throw new Error("Access probe returned JSON but not a project array");
        }
        emit(
          log,
          "INFO",
          "Access probe accepted the token and returned " +
          projects.length +
          " project(s)",
        );
        emit(log, "INFO", "Access diagnosis completed successfully");
        return {
          token: diagnostic,
          apiProbe: {
            url: url,
            accepted: true,
            responseShape: "project-array",
            projectCount: projects.length,
          },
        };
      } catch (error) {
        var contextual = contextualError("diagnose access", error);
        emit(log, "ERROR", contextual.message);
        throw contextual;
      }
    }
    return {
      diagnoseAccess: diagnoseAccess,
      getParticipant: getParticipant,
      getParticipantUrl: getParticipantUrl,
    };
  }
  return createVistaApi({ get: vista_forstaHttpGet, post: vista_forstaHttpPost }, forstaLogger);
}

// src/forsta-entry.js
function vista_escapeHtml(value) {
  return value
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/\"/g, "&quot;")
    .replace(/'/g, "&#39;");
}
function forstaLogger(level, message) {
  var line =
    /* @__PURE__ */ new Date().toISOString() + " [" + level + "] " + message;
  var logQuestion = f("execution_log");
  var currentLog = logQuestion.get();
  logQuestion.set(
    typeof currentLog === "string" && currentLog !== ""
      ? currentLog + "\n" + line
      : line,
  );
  if (IsInProductionMode() == false) {
    Response.Write("<pre>" + vista_escapeHtml(line) + "</pre>");
  }
}
function vista_forstaHttpGet(url, data, headers) {
  return Http.Get(url, data, headers);
}

function vista_forstaHttpPost(url, data, headers) {
  return Http.Post(url, data, headers);
}

function vista_getParticipant(config, projectId, participantId) {
  return vista_createApi().getParticipant(config, projectId, participantId);
}

function vista_getParticipantUrl(config, projectId, participantId, returnSpec) {
  return vista_createApi().getParticipantUrl(config, projectId, participantId, returnSpec);
}

function vista_diagnoseAccess(config) {
  return vista_createApi().diagnoseAccess(config);
}

