function init(qid, initValue) {
    const q = f(qid);
    if (!q.toBoolean()) {
        forstaLogger("INFO",  `Initialising state variable '${qid}' to value ${initValue}`)
        q.set(initValue);
    }
}

init("screening_complete", "0");
init("td_intro_actioned", "0");
init("consent_complete", "0");
init("logicly_status", "incomplete");
init("logicly_id", f("Id").get());
init("travel_day", f("adhoc_1").get());

function vista_getMelbourneUtcOffsetMinutes(instant = new Date()) {
  const t = instant instanceof Date ? instant.getTime() : Number(instant);
  if (!Number.isFinite(t)) throw new TypeError("instant must be a Date or epoch milliseconds");

  const d = new Date(t);
  const y = d.getUTCFullYear();
  const m = d.getUTCMonth(); // 0=Jan ... 11=Dec

  // Helper: day-of-month for first Sunday of a month (computed using UTC calendar)
  function firstSundayDayOfMonth(year, monthIndex /* 0-11 */) {
    const first = new Date(Date.UTC(year, monthIndex, 1, 0, 0, 0));
    const dow = first.getUTCDay(); // 0=Sun ... 6=Sat
    const delta = (7 - dow) % 7;   // days to add to reach Sunday
    return 1 + delta;
  }

  // Build UTC instant for DST start: first Sunday Oct at 02:00 AEST => Sat 16:00 UTC
  function dstStartUtcMillis(year) {
    const firstSundayOct = firstSundayDayOfMonth(year, 9); // October
    return Date.UTC(year, 9, firstSundayOct - 1, 16, 0, 0); // previous day 16:00 UTC
  }

  // Build UTC instant for DST end: first Sunday Apr at 03:00 AEDT => Sat 16:00 UTC
  function dstEndUtcMillis(year) {
    const firstSundayApr = firstSundayDayOfMonth(year, 3); // April
    return Date.UTC(year, 3, firstSundayApr - 1, 16, 0, 0); // previous day 16:00 UTC
  }

  // Southern hemisphere season spans years:
  // - If we're in Oct-Dec: compare to start this year and end next year.
  // - If we're in Jan-Sep: compare to start last year and end this year.
  let start, end;
  if (m >= 9) { // Oct/Nov/Dec
    start = dstStartUtcMillis(y);
    end = dstEndUtcMillis(y + 1);
  } else { // Jan..Sep
    start = dstStartUtcMillis(y - 1);
    end = dstEndUtcMillis(y);
  }

  const isDst = t >= start && t < end;
  return isDst ? 11 * 60 : 10 * 60;
}

function vista_getMelbourneMidnight(year, month, day) {
    const AEST_OFFSET_MINUTES = 10 * 60;

    // First construct midnight assuming AEST. This candidate is close enough
    // to the intended Melbourne midnight to determine whether AEST or AEDT
    // applies on that date.
    const aestCandidate =
        Date.UTC(year, month, day, 0, 0, 0) -
        AEST_OFFSET_MINUTES * 60 * 1000;

    // Determine whether Melbourne is on AEST (+10) or AEDT (+11) at
    // this midnight.
    const offsetMinutes =
        vista_getMelbourneUtcOffsetMinutes(aestCandidate);

    // Convert Melbourne local midnight to the corresponding UTC instant.
    const utcMillis =
        Date.UTC(year, month, day, 0, 0, 0) -
        offsetMinutes * 60 * 1000;

    return new Date(utcMillis);
}


function vista_getTravelDayStartTime() {
    const travelDay = new Date(f("travel_day").get());

    if (!Number.isFinite(travelDay.getTime())) {
        throw new TypeError("travel_day must be a valid Date");
    }

    const year = travelDay.getUTCFullYear();
    const month = travelDay.getUTCMonth();
    const day = travelDay.getUTCDate();

    const startTime =
        vista_getMelbourneMidnight(year, month, day);

    forstaLogger(
        "DEBUG",
        "VISTA travel day start calculated: " +
            "travel_day=" + JSON.stringify(f("travel_day").get()) +
            ", start=" + startTime.toISOString()
    );

    return startTime;
}

function vista_getSurveyCloseTime() {
    const N_OPEN_DAYS = 8;

    const travelDay = new Date(f("travel_day").get());

    if (!Number.isFinite(travelDay.getTime())) {
        throw new TypeError("travel_day must be a valid Date");
    }

    const year = travelDay.getUTCFullYear();
    const month = travelDay.getUTCMonth();
    const day = travelDay.getUTCDate() + N_OPEN_DAYS;

    const closeTime =
        vista_getMelbourneMidnight(year, month, day);

    forstaLogger(
        "DEBUG",
        "VISTA survey close calculated: " +
            "travel_day=" + JSON.stringify(f("travel_day").get()) +
            ", close=" + closeTime.toISOString()
    );

    return closeTime;
}

function ordinal(n) {
    if (n % 100 >= 11 && n % 100 <= 13) {
        return `${n}th`;
    }

    switch (n % 10) {
        case 1: return `${n}st`;
        case 2: return `${n}nd`;
        case 3: return `${n}rd`;
        default: return `${n}th`;
    }
}

function formatLongDate(date) {
    const days = [
        "Sunday", "Monday", "Tuesday", "Wednesday",
        "Thursday", "Friday", "Saturday"
    ];

    const months = [
        "January", "February", "March", "April",
        "May", "June", "July", "August",
        "September", "October", "November", "December"
    ];

    return `${days[date.getDay()]} ${ordinal(date.getDate())} ${months[date.getMonth()]}`;
}

function formatShortDate(date) {
    const days = [
        "Sunday", "Monday", "Tuesday", "Wednesday",
        "Thursday", "Friday", "Saturday"
    ];

    return `${days[date.getDay()]} ${ordinal(date.getDate())}`;
}

function vista_getTravelDayLong() {
    const travelDay = f("travel_day").get();
    return formatLongDate(new Date(travelDay));
}

function vista_getTravelDayShort() {
    const travelDay = f("travel_day").get();
    return formatShortDate(new Date(travelDay));
}

function vista_refreshCompletionStatus() {
  const vistaConfig = vista_getConfig();

  let participant;
  try {
    participant = vista_getParticipant(
      vistaConfig,
      vistaConfig.projectId,
      f("logicly_id").get(),
    );
  } catch (error) {
    forstaLogger(
      "ERROR",
      "Was unable to retrieve participant from logicly. Recieved error: " +
      error.message +
      ". Trying again",
    );
    try {
      participant = vista_getParticipant(
        vistaConfig,
        vistaConfig.projectId,
        f("logicly_id").get(),
      );
    } catch (error) {
      forstaLogger(
        "FATAL",
        "Was unable to retrieve participant from logicly a second time. Recieved error: " +
        error.message +
        "Fatal error",
      );
      throw new Error(error);
    }
  }

  forstaLogger(
    "INFO",
    "Got participant " + JSON.stringify(participant),
  );

  const completionStatus = participant.surveyStatus;
  const updatedAt = new Date().toISOString();

  if (!completionStatus) {
    const msg = "API did not return `surveyStatus` field. Cannot proceed";
    forstaLogger("FATAL", msg);
    throw new Error(msg);
  }

  if (completionStatus === "submit-complete" || completionStatus === "submit-incomplete") {
    f("logicly_status").set("complete");
  }
  f("logicly_status_updated_at").set(updatedAt);

  forstaLogger(
    "INFO",
    `logicly_status updated to: ${f("logicly_status").get()}`,
  );
}

function logAndThrowError(message) {
  forstaLogger("ERROR", "VISTA state resolver: " + message);
  throw new Error(message);
}

function vista_getUrlParameter(url, name) {
  if (!url || !name) {
    return null;
  }

  var queryStart = url.indexOf("?");

  if (queryStart === -1) {
    return null;
  }

  var query = url.substring(queryStart + 1);
  var parts = query.split("&");

  for (var i = 0; i < parts.length; i++) {
    var equalsIndex = parts[i].indexOf("=");

    var key;
    var value;

    if (equalsIndex === -1) {
      key = parts[i];
      value = "";
    } else {
      key = parts[i].substring(0, equalsIndex);
      value = parts[i].substring(equalsIndex + 1);
    }

    if (key === name) {
      return value;
    }
  }

  return null;
}


/*
 * Use a function rather than a top-level const/var so that state definitions
 * remain available when VISTA functions are called from other script nodes.
 */
function vista_getStates() {
  return {
    SCREENING: 1,
    PRE_TD: 2,
    TD_INTRO: 3,
    CONSENT: 4,
    ACTIVE: 5,
    COMPLETE: 6,
    EXPIRED: 7
  };
}


function vista_getStateName(state) {
  var VISTA_STATE = vista_getStates();

  switch (state) {
    case VISTA_STATE.SCREENING:
      return "SCREENING";
    case VISTA_STATE.PRE_TD:
      return "PRE_TD";
    case VISTA_STATE.TD_INTRO:
      return "TD_INTRO";
    case VISTA_STATE.CONSENT:
      return "CONSENT";
    case VISTA_STATE.ACTIVE:
      return "ACTIVE";
    case VISTA_STATE.COMPLETE:
      return "COMPLETE";
    case VISTA_STATE.EXPIRED:
      return "EXPIRED";
    default:
      return "UNKNOWN";
  }
}


function vista_parseBooleanFlag(name, value) {
  if (value === "1" || value === 1 || value === true) {
    return true;
  }

  if (value === "0" || value === 0 || value === false) {
    return false;
  }

  var message =
    "Unexpected value for " +
    name +
    ": " +
    JSON.stringify(value);

  logAndThrowError(message);
}


function vista_resolveState(now) {
  try {
    var VISTA_STATE = vista_getStates();

    if (typeof now === "undefined") {
      now = new Date();
    }

    if (!(now instanceof Date) || !Number.isFinite(now.getTime())) {
      logAndThrowError("now must be a valid Date");
    }

    forstaLogger(
      "INFO",
      "VISTA state resolver started; now=" + now.toISOString()
    );

    vista_refreshCompletionStatus();

    // -----------------------------------------------------------------
    // Read persisted participant state
    // -----------------------------------------------------------------

    var rawScreeningComplete = f("screening_complete").get();
    var rawTdIntroActioned = f("td_intro_actioned").get();
    var rawConsentComplete = f("consent_complete").get();
    var rawLogiclyStatus = f("logicly_status").get();
    var rawTravelDay = f("travel_day").get();

    forstaLogger(
      "DEBUG",
      "VISTA persisted state: " +
      "screening_complete=" + JSON.stringify(rawScreeningComplete) +
      ", td_intro_actioned=" + JSON.stringify(rawTdIntroActioned) +
      ", consent_complete=" + JSON.stringify(rawConsentComplete) +
      ", logicly_status=" + JSON.stringify(rawLogiclyStatus) +
      ", travel_day=" + JSON.stringify(rawTravelDay)
    );

    var screeningComplete = vista_parseBooleanFlag(
      "screening_complete",
      rawScreeningComplete
    );

    var tdIntroActioned = vista_parseBooleanFlag(
      "td_intro_actioned",
      rawTdIntroActioned
    );

    var consentComplete = vista_parseBooleanFlag(
      "consent_complete",
      rawConsentComplete
    );

    var logiclyStatus = String(rawLogiclyStatus || "")
      .trim()
      .toLowerCase();

    // -----------------------------------------------------------------
    // Validate participant state
    // -----------------------------------------------------------------

    if (
      logiclyStatus !== "complete" &&
      logiclyStatus !== "incomplete"
    ) {
      logAndThrowError(
        "Unexpected logicly_status: " +
        JSON.stringify(rawLogiclyStatus)
      );
    }

    if (tdIntroActioned && !screeningComplete) {
      logAndThrowError(
        "Invalid VISTA state: " +
        "td_intro_actioned=1 but screening_complete=0"
      );
    }

    if (consentComplete && !tdIntroActioned) {
      logAndThrowError(
        "Invalid VISTA state: consent_complete=1 " +
        "but td_intro_actioned=0"
      );
    }

    forstaLogger(
      "DEBUG",
      "VISTA persisted state validated successfully"
    );

    // -----------------------------------------------------------------
    // Calculate time boundaries
    // -----------------------------------------------------------------

    var travelDayStartTime = vista_getTravelDayStartTime();
    var surveyCloseTime = vista_getSurveyCloseTime();

    if (
      !(travelDayStartTime instanceof Date) ||
      !Number.isFinite(travelDayStartTime.getTime())
    ) {
      logAndThrowError(
        "vista_getTravelDayStartTime() did not return a valid Date"
      );
    }

    if (
      !(surveyCloseTime instanceof Date) ||
      !Number.isFinite(surveyCloseTime.getTime())
    ) {
      logAndThrowError(
        "vista_getSurveyCloseTime() did not return a valid Date"
      );
    }

    forstaLogger(
      "DEBUG",
      "VISTA time boundaries: " +
      "travel_day_start=" + travelDayStartTime.toISOString() +
      ", survey_close=" + surveyCloseTime.toISOString() +
      ", now=" + now.toISOString()
    );

    var nowMillis = now.getTime();
    var travelDayStartMillis = travelDayStartTime.getTime();
    var surveyCloseMillis = surveyCloseTime.getTime();

    // -----------------------------------------------------------------
    // Resolve state
    // -----------------------------------------------------------------

    var resolvedState;
    var reason;

    if (logiclyStatus === "complete") {
      resolvedState = VISTA_STATE.COMPLETE;
      reason = "Logicly status is complete";

    } else if (nowMillis >= surveyCloseMillis) {
      resolvedState = VISTA_STATE.EXPIRED;
      reason =
        "survey close time reached and Logicly status is incomplete";

    } else if (!screeningComplete) {
      resolvedState = VISTA_STATE.SCREENING;
      reason = "screening has not been completed";

    } else if (nowMillis < travelDayStartMillis) {
      resolvedState = VISTA_STATE.PRE_TD;
      reason =
        "screening complete but Travel Day has not started";

    } else if (!tdIntroActioned) {
      resolvedState = VISTA_STATE.TD_INTRO;
      reason =
        "Travel Day has started and TD intro has not been actioned";

    } else if (!consentComplete) {
      resolvedState = VISTA_STATE.CONSENT;
      reason =
        "TD intro actioned but consent has not been completed";

    } else {
      resolvedState = VISTA_STATE.ACTIVE;
      reason =
        "consent complete, survey open, Logicly status incomplete";
    }

    forstaLogger(
      "INFO",
      "VISTA state resolved: " +
      resolvedState +
      " (" +
      vista_getStateName(resolvedState) +
      "); reason=" +
      reason
    );

    return resolvedState;

  } catch (error) {
    var message =
      error && error.message
        ? error.message
        : String(error);

    forstaLogger(
      "ERROR",
      "VISTA state resolver failed: " + message
    );

    throw error;
  }
}


