//       target +
//       "` failed: " +
//       message
//     );

//     throw error;
//   }
// }

function vista_redirect(target, isCallBlock) {
  if (!target) {
    logAndThrowError(
      "vista_redirect() requires a non-empty target"
    );
  }

  if (typeof isCallBlock === "undefined") {
    isCallBlock = false;
  }

  try {
    /*
     * Generate a target-specific respondent URL.
     *
     * The destination is encoded by Forsta into the encrypted
     * respondent URL.
     */
    var targetUrl = GetRespondentUrl(
      target,
      isCallBlock
    );

    if (!targetUrl) {
      throw new Error(
        "GetRespondentUrl() returned an empty URL"
      );
    }

    /*
     * Keep the encrypted SID associated with this internal route.
     *
     * Start uses this to distinguish the exact internal URL generated
     * here from an ordinary survey entry, browser Back navigation, or
     * some other stale respondent URL.
     */
    var targetSid =
      vista_getUrlParameter(targetUrl, "__sid__");

    if (!targetSid) {
      throw new Error(
        "Generated respondent URL does not contain __sid__"
      );
    }

    f("vista_internal_sid").set(targetSid);

    forstaLogger(
      "INFO",
      "Redirecting internally to `" +
      target +
      "`" +
      (isCallBlock ? " as Call Block" : "")
    );

    /*
     * Do not log targetUrl or targetSid. The generated respondent URL
     * should be treated as a respondent re-entry credential.
     *
     * Redirect rather than RedirectToRespondentUrl so the browser's
     * address bar is updated. This makes Refresh repeat the same
     * targeted request.
     */
    Redirect(targetUrl, true);

  } catch (error) {
    var message =
      error && error.message
        ? error.message
        : String(error);

    forstaLogger(
      "ERROR",
      "Internal redirect to `" +
      target +
      "` failed: " +
      message
    );

    throw error;
  }
}


function vista_route() {
  var VISTA_STATE = vista_getStates();
  var resolvedState = vista_resolveState();

  switch (resolvedState) {
    case VISTA_STATE.SCREENING:
      /*
       * Screening is at the beginning of the normal questionnaire path,
       * so no redirect is required.
       */
      forstaLogger(
        "INFO",
        "Routing state is SCREENING; continuing normal questionnaire flow"
      );
      return;

    case VISTA_STATE.PRE_TD:
      vista_redirect("pre_travel_day_landing");
      return;

    case VISTA_STATE.TD_INTRO:
      vista_redirect("travel_day_landing");
      return;

    case VISTA_STATE.CONSENT:
      vista_redirect("travel_day_landing");
      return;

    case VISTA_STATE.ACTIVE:
      vista_redirect("active_survey");
      return;

    case VISTA_STATE.COMPLETE:
      vista_redirect(
        "vista_completed_survey",
        true
      );
      return;

    case VISTA_STATE.EXPIRED:
      vista_redirect(
        "vista_expired_survey",
        true
      );
      return;

    default:
      logAndThrowError(
        "Encountered an unknown state for routing: " +
        resolvedState +
        " (" +
        vista_getStateName(resolvedState) +
        ")"
      );
  }
}


// /*
//  * -------------------------------------------------------------------
//  * Start-block dispatch
//  * -------------------------------------------------------------------
//  *
//  * Every entry into the survey passes through this block.
//  *
//  * RedirectToRespondentUrl() also causes the interview to be re-entered,
//  * so an internal redirect executes this Start block a second time.
//  *
//  * vista_internal_target is therefore used as a one-shot marker:
//  *
//  *   normal entry
//  *     -> vista_route()
//  *     -> vista_redirect()
//  *     -> set vista_internal_target
//  *     -> Forsta re-enters interview
//  *
//  *   internal re-entry
//  *     -> detect vista_internal_target
//  *     -> clear marker
//  *     -> skip vista_route()
//  *     -> Forsta continues to requested target
//  */

// var internalTarget = f("vista_internal_target").get();

// if (internalTarget) {
//   forstaLogger(
//     "INFO",
//     "Internal re-entry detected for target `" +
//     internalTarget +
//     "`; consuming marker and skipping VISTA dispatcher"
//   );

//   /*
//    * Consume the marker immediately.
//    *
//    * Any later genuine entry into the survey must run the dispatcher
//    * normally.
//    */
//   f("vista_internal_target").set("");

// } else {
//   forstaLogger(
//     "INFO",
//     "No internal re-entry marker found; running VISTA dispatcher"
//   );

//   vista_route();
// }

var requestSid =
  Request.QueryString.item("__sid__");

var internalSid =
  f("vista_internal_sid").get();

if (
  requestSid != null &&
  internalSid &&
  String(requestSid) === String(internalSid)
) {
  forstaLogger(
    "INFO",
    "Internal VISTA re-entry detected; " +
    "current respondent URL matches expected internal route"
  );

} else {
  forstaLogger(
    "INFO",
    "Normal or stale survey entry; running VISTA dispatcher"
  );

  vista_route();
}

